package packages

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
	"path/filepath"
	"slices"
	"strconv"
	"strings"

	"golang.org/x/tools/go/ast/astutil"
)

// setAside loads again with the regenerated files of set that keep it from
// loading replaced, in the steps Load describes.
func setAside(patterns []string, cfg Config, set Set) (Set, error) {
	// The type checker skips every file that declares another package than the
	// first it reads, so until the misnamed files are gone, the errors say little
	// about which of the rest are stale.
	misnamed := misnamedFiles(set, cfg.Regenerated)
	overlay := make(map[string][]byte, len(misnamed))
	emptied := make([]string, 0, len(misnamed))
	for _, f := range misnamed {
		overlay[f.path] = emptyFile(f.pkg)
		emptied = append(emptied, f.path)
	}
	if len(misnamed) > 0 {
		var err error
		if set, err = load(patterns, cfg, overlay); err != nil {
			return Set{}, err
		}
	}

	set, err := setAsideStale(patterns, cfg, set, overlay, emptied)
	if err != nil {
		return Set{}, err
	}
	set.SetAside = append(set.SetAside, emptied...)
	slices.Sort(set.SetAside)
	return set, nil
}

// setAsideStale loads again with the stale regenerated files of set replaced
// too, adding to overlay. The files already emptied stay so: an error can still
// point into one while a file not regenerated declares the old package name.
func setAsideStale(patterns []string, cfg Config, set Set, overlay map[string][]byte, emptied []string) (Set, error) {
	stale := staleFiles(set, cfg.Regenerated, emptied)
	if len(stale) == 0 {
		return set, nil
	}

	// A file that cannot be stubbed, such as one that no longer parses, is left
	// as it is here and emptied by the second step.
	for _, f := range stale {
		if stub, ok := stubBodies(f.path); ok {
			overlay[f.path] = stub
		}
	}
	set, err := load(patterns, cfg, overlay)
	if err != nil {
		return Set{}, err
	}

	still := staleFiles(set, cfg.Regenerated, emptied)
	if len(still) == 0 {
		return set, nil
	}
	for _, f := range still {
		overlay[f.path] = emptyFile(f.pkg)
	}
	set, err = load(patterns, cfg, overlay)
	if err != nil {
		return Set{}, err
	}
	for _, f := range still {
		set.SetAside = append(set.SetAside, f.path)
	}
	return set, nil
}

// emptyFile is what stands in for a file set aside: a generated file declaring
// pkg and nothing else.
func emptyFile(pkg string) []byte {
	return fmt.Appendf(nil, "// Code generated by kanna. DO NOT EDIT.\n\npackage %s\n", pkg)
}

// staleFile is a regenerated file that keeps its package from loading.
type staleFile struct {
	path string
	pkg  string // the package the file is to declare
}

// misnamedFiles lists the generated files in set, named one of regenerated, that
// declare another package than the hand-written files of their package, which
// all declare the same one, sorted by path. The hand-written files are what
// name a package; the generated ones only follow.
func misnamedFiles(set Set, regenerated []string) []staleFile {
	var misnamed []staleFile
	for _, p := range set.Packages {
		generated := GeneratedFiles(p)
		var (
			own  []staleFile
			want []string
		)
		for _, f := range p.Syntax {
			path := p.Fset.Position(f.Pos()).Filename
			switch {
			case !generated[path]:
				want = append(want, f.Name.Name)
			case slices.Contains(regenerated, filepath.Base(path)):
				own = append(own, staleFile{path: path, pkg: f.Name.Name})
			}
		}

		slices.Sort(want)
		if want = slices.Compact(want); len(want) != 1 {
			continue
		}
		for _, f := range own {
			if f.pkg != want[0] {
				misnamed = append(misnamed, staleFile{path: f.path, pkg: want[0]})
			}
		}
	}
	slices.SortFunc(misnamed, func(a, b staleFile) int { return strings.Compare(a.path, b.path) })
	return misnamed
}

// staleFiles lists the generated files in set, named one of regenerated and not
// one of except, that an error points into, sorted by path.
func staleFiles(set Set, regenerated, except []string) []staleFile {
	broken := make(map[string]bool)
	for _, d := range set.Diags {
		broken[d.Pos.Filename] = true
	}

	var stale []staleFile
	for _, p := range set.Packages {
		for path := range GeneratedFiles(p) {
			if broken[path] && slices.Contains(regenerated, filepath.Base(path)) && !slices.Contains(except, path) {
				stale = append(stale, staleFile{path: path, pkg: p.Name})
			}
		}
	}
	slices.SortFunc(stale, func(a, b staleFile) int { return strings.Compare(a.path, b.path) })
	return stale
}

// stubBodies returns the file at path with every function body replaced by a
// panic, or false when the file cannot be read as Go. An import that only the
// bodies used is renamed to _, or the stub would fail on it instead.
func stubBodies(path string) ([]byte, bool) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, path, nil, parser.ParseComments)
	if err != nil {
		return nil, false
	}

	var bodies []*ast.BlockStmt
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			continue
		}
		bodies = append(bodies, fn.Body)
		fn.Body = &ast.BlockStmt{List: []ast.Stmt{&ast.ExprStmt{X: &ast.CallExpr{
			Fun:  ast.NewIdent("panic"),
			Args: []ast.Expr{&ast.BasicLit{Kind: token.STRING, Value: strconv.Quote("stale")}},
		}}}}
	}

	// A comment from a dropped body would otherwise be printed somewhere else.
	file.Comments = slices.DeleteFunc(file.Comments, func(cg *ast.CommentGroup) bool {
		return slices.ContainsFunc(bodies, func(b *ast.BlockStmt) bool {
			return b.Pos() <= cg.Pos() && cg.End() <= b.End()
		})
	})

	for _, spec := range file.Imports {
		if p, err := strconv.Unquote(spec.Path.Value); err == nil && !astutil.UsesImport(file, p) {
			spec.Name = ast.NewIdent("_")
		}
	}

	var buf bytes.Buffer
	if err := printer.Fprint(&buf, fset, file); err != nil {
		return nil, false
	}
	return buf.Bytes(), true
}
